<?php
require_once __DIR__.'/../includes/auth.php';require_login();$company=require __DIR__.'/../config/company.php';
$s=db()->prepare('SELECT s.*,c.name customer_name,c.code customer_code,c.phone,c.address FROM shipments s JOIN customers c ON c.id=s.customer_id WHERE s.id=?');$s->execute([(int)($_GET['id']??0)]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Shipment not found.');}
$s=db()->prepare('SELECT * FROM shipment_items WHERE shipment_id=? ORDER BY id');$s->execute([$r['id']]);$items=$s->fetchAll();$itemsTotal=0;foreach($items as $item)$itemsTotal+=(float)$item['quantity']*(float)$item['price'];$total=$r['price']!==null?(float)$r['price']:$itemsTotal;
audit_log('receipt_viewed','shipment',(int)$r['id'],['jtr_number'=>$r['jtr_number']]);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt <?=e($r['jtr_number'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{font-family:Arial,sans-serif;color:#111}.receipt{max-width:1100px;margin:24px auto}.receipt-head{border:2px dashed #111;padding:20px}.receipt-logo{width:190px;max-height:120px;object-fit:contain}.brand{color:#e40b78}.phones{font-size:12px;line-height:1.65}.meta,.items{width:100%;border-collapse:collapse}.meta td,.items th,.items td{border:1px solid #777;padding:9px}.meta .label,.items th{background:#f0f0f0;font-weight:700}.total{font-size:1.2rem;font-weight:700}.no-print{margin:20px auto;max-width:1100px}@media print{.no-print{display:none}.receipt{margin:0;max-width:none}@page{margin:10mm}}</style></head><body><div class="no-print"><button class="btn btn-primary" onclick="window.print()">Print Receipt</button> <a class="btn btn-light" href="shipments.php">Back</a></div><main class="receipt"><section class="receipt-head d-flex justify-content-between align-items-center gap-4"><img src="../<?=e($company['logo'])?>" class="receipt-logo" alt="<?=e($company['company_name'])?>"><div class="text-end"><h1 class="h2 fw-bold brand"><?=e($company['company_name'])?></h1><strong>Shipment Receipt</strong><div class="phones"><div><strong>Iraq:</strong> <?=e($company['iraq_phone'])?></div><div><strong>UAE:</strong> <?=e($company['dubai_phone'])?></div><div><strong>Turkey:</strong> <?=e($company['turkey_phone'])?></div></div><div><?=e(date('Y-m-d'))?></div></div></section><table class="meta my-3"><tr><td class="label">Client</td><td><?=e($r['customer_name'])?></td><td class="label">Phone</td><td><?=e($r['phone']?:'-')?></td></tr><tr><td class="label">Code</td><td><?=e($r['customer_code'])?></td><td class="label">Address</td><td><?=e($r['address']?:'-')?></td></tr><tr><td class="label">Brand / JTR</td><td><?=e(($r['brand_name']?:'-').' / '.$r['jtr_number'])?></td><td class="label">Weight / Status</td><td><?=e(rtrim(rtrim($r['weight'],'0'),'.').' KG / '.status_labels()[$r['status']])?></td></tr></table><table class="items"><thead><tr><th>No.</th><th>Product Name</th><th>Brand</th><th>Quantity</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i=>$item):$line=(float)$item['quantity']*(float)$item['price'];?><tr><td><?=$i+1?></td><td><?=e($item['product_name'])?></td><td><?=e($item['brand']?:'-')?></td><td><?=e($item['quantity'])?></td><td>$ <?=number_format((float)$item['price'],2)?></td><td>$ <?=number_format($line,2)?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6" class="text-center">No items</td></tr><?php endif;?></tbody></table><div class="total mt-3 text-end">Total Price: $ <?=number_format($total,2)?></div></main></body></html>
